(7424438, 1172457, 142425, '<td valign="top">p<br/> <br/>NB: This is NOT my comment. My account appear to have been highjacked.<br/>Mond.<br/><br/><i>Message edited by author 2016-03-31 11:31:20.</i></td>', 'p NB: This is NOT my comment. My account appear to have been highjacked.Mond.', '2015-12-28 03:20:48.000000', '2016-03-31 12:31:20.000000', 1),
(7424464, 1172472, 59029, '<td valign="top">love the mailbox post</td>', 'love the mailbox post', '2015-12-28 09:51:18.000000', NULL, 1),
(7424475, 1172433, 60173, '<td valign="top">I might have shot this at a slightly higher angle. As it is now, the words in the letter took some effort to read.</td>', 'I might have shot this at a slightly higher angle. As it is now, the words in the letter took some effort to read.', '2015-12-28 11:51:06.000000', NULL, 1),
(7424476, 1172323, 60173, '<td valign="top">I guess those are less "mailboxes" and more "mailbuckets". As I sat and looked at this photo, I admired these buckets at first, but the more I look at them, I have to wonder how short people get their mail. <br/> <br/>As for the photo, I like the processing and the leading lines.</td>', 'I guess those are less "mailboxes" and more "mailbuckets". As I sat and looked at this photo, I admired these buckets at first, but the more I look at them, I have to wonder how short people get their mail.  As for the photo, I like the processing and the leading lines.', '2015-12-28 11:59:22.000000', NULL, 1),
(7424491, 1172181, 91342, '<td valign="top">I can''t see the envelope.  Looks like corners of frames.</td>', 'I can''t see the envelope.  Looks like corners of frames.', '2015-12-28 14:24:15.000000', NULL, 1),
